/* ============================================================
   أطياب الجاسم (React) — زر الدخول بجوجل (GoogleSignIn)

   زر Google Identity Services الرسمي (ليس زراً مرسوماً يدوياً):
     · يُحمَّل سكربت https://accounts.google.com/gsi/client مرة واحدة.
     · يُرسم عبر google.accounts.id.renderButton (بلا One Tap منبثق).
     · عند النجاح نستلم idToken (JWT خام) ونسلّمه للأب — وهو يرسله
       للخادم POST /api/auth/google الذي يتحقق منه لدى Google ويرجع
       نفس شكل الجلسة (access + refresh + customerId).

   ★ فكّ الترميز في المتصفح للعرض فقط — الثقة حصراً بتحقق الخادم
     (aud = الـ Client ID، iss، exp، ثم sub كمفتاح ثابت للحساب).
   ★ الـ Client ID علني (ليس سراً): window.ATYAB_GOOGLE_CLIENT_ID
     أو localStorage ‏«atyab:googleClientId» — وبدونه يظهر سطر إعداد
     بدل الزر. أضِف origin الموقع في Authorized JavaScript origins.
   ============================================================ */

import { useEffect, useRef, useState } from "react";
import { useAppSelector } from "../../redux/hooks.js";
import { readGoogleClientId } from "../../api/auth.js";
import "../Skeletons/Skeletons.css";

const GIS_SRC = "https://accounts.google.com/gsi/client";

let gisPromise = null;
let gisClient = "";

function loadGis() {
  if (gisPromise) return gisPromise;
  gisPromise = new Promise(function (resolve, reject) {
    try {
      if (window.google && window.google.accounts && window.google.accounts.id) {
        resolve();
        return;
      }
      const s = document.createElement("script");
      s.src = GIS_SRC;
      s.async = true;
      s.defer = true;
      s.onload = function () {
        resolve();
      };
      s.onerror = function () {
        gisPromise = null;
        reject(new Error("gis-load"));
      };
      document.head.appendChild(s);
    } catch (e) {
      gisPromise = null;
      reject(e);
    }
  });
  return gisPromise;
}

export default function GoogleSignIn(props) {
  const btnRef = useRef(null);
  const cbRef = useRef(null);
  cbRef.current = props.onCredential;
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const [state, setState] = useState("loading");
  const [night, setNight] = useState(false);
  const clientId = readGoogleClientId();
  const mode = props.mode === "signup" ? "signup" : "login";

  /* ★ R19: ثيم الزر يتبع ثيم الموقع (زر جوجل الرسمي لا يقبل CSS —
     GIS يرسم iframe، فالثيم والشكل والحجم هي أدوات التنسيق المتاحة). */
  useEffect(function () {
    function sync() {
      try {
        setNight(document.documentElement.getAttribute("data-theme") === "night");
      } catch (e) {}
    }
    sync();
    let obs = null;
    try {
      obs = new MutationObserver(sync);
      obs.observe(document.documentElement, { attributes: true, attributeFilter: ["data-theme"] });
    } catch (e) {}
    return function () {
      try {
        if (obs) obs.disconnect();
      } catch (e) {}
    };
  }, []);

  useEffect(
    function () {
      if (!clientId) {
        setState("noclient");
        return;
      }
      let alive = true;
      setState("loading");
      loadGis().then(
        function () {
          if (!alive) return;
          try {
            /* ★ تهيئة مرة واحدة لكل Client ID — الاستدعاء المتكرر
               (تبديل اللغة/الوضع) يعيد رسم الزر فقط بلا تهيئة جديدة */
            if (gisClient !== clientId) {
              window.google.accounts.id.initialize({
                client_id: clientId,
                callback: function (resp) {
                  if (resp && resp.credential && cbRef.current) cbRef.current(resp.credential);
                },
                auto_select: false,
                cancel_on_tap_outside: true
              });
              gisClient = clientId;
            }
            if (btnRef.current) {
              try {
                if (typeof btnRef.current.replaceChildren === "function") btnRef.current.replaceChildren();
                else while (btnRef.current.firstChild) btnRef.current.removeChild(btnRef.current.firstChild);
              } catch (e) {}
              /* ★ R19: يطابق الموقع قدر المستطاع — زر جوجل الرسمي iframe
                 (سياسة جوجل تمنع تنسيقه بـCSS)، فالمتاح: الشكل والحجم والثيم */
              let w = 300;
              try {
                const cw = btnRef.current.clientWidth || 0;
                if (cw > 0) w = Math.max(240, Math.min(400, cw));
              } catch (e) {}
              window.google.accounts.id.renderButton(btnRef.current, {
                theme: night ? "filled_black" : "outline",
                shape: "pill",
                size: "large",
                width: w,
                text: mode === "signup" ? "signup_with" : "signin_with",
                locale: language === "en" ? "en" : "ar"
              });
            }
            setState("ready");
          } catch (e) {
            setState("failed");
            if (props.onError) props.onError();
          }
        },
        function () {
          if (!alive) return;
          setState("failed");
          if (props.onError) props.onError();
        }
      );
      return function () {
        alive = false;
      };
    },
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [clientId, mode, language, night]
  );

  if (!clientId) {
    return (
      <>
        <div className="rg-or">
          <span>أو</span>
        </div>
        <p className="rg-note">
          <span>الدخول بجوجل يفعَّل بإضافة Google Client ID (window.ATYAB_GOOGLE_CLIENT_ID) — راجع مالك المتجر.</span>
        </p>
      </>
    );
  }

  return (
    <>
      <div className="rg-or">
        <span>أو</span>
      </div>
      <div className="rg-google-wrap">
        <div ref={btnRef} className="rg-google-official" />
        {state === "loading" ? <span className="sk-block sk-btn rg-google-sk" role="status" aria-label="يُجهَّز زر جوجل" /> : null}
        {state === "failed" ? (
          <button
            className="rg-google"
            type="button"
            onClick={function () {
              if (props.onError) props.onError();
            }}
          >
            <span className="rg-google-text">تعذّر تحميل زر جوجل — اضغط لإعادة المحاولة</span>
          </button>
        ) : null}
      </div>
    </>
  );
}
