/* ============================================================
   أطياب الجاسم (React) — نافذة تسجيل الدخول / إنشاء حساب (LogIn)

   وضعان في كومبوننت واحد:
     mode="signup" → إنشاء حساب جديد (البريد + كلمة المرور وتأكيدها +
                     الموافقة على الشروط) — بقية البيانات عند Checkout.
     mode="login"  → تسجيل الدخول (البريد + كلمة المرور).

   ★ التوافقية: النافذة مصمّمة لتعمل على اللابتوب والهاتف معاً —
     عمود واحد على الهاتف وعمودان للحقول القصيرة على الشاشات الواسعة،
     مع تمرير داخلي وارتفاع لا يتجاوز الشاشة، وأزرار بحجم لمس مريح.

   ★ الأمان: الخادم أولاً — signup/login عبر /api/auth فيُرجع Access +
     Refresh Token يُحفظان محلياً (الـ access ~ساعة والـ refresh ١٤ يوماً
     بلا ثانية تأخير: تجديد صامت). ومع غياب الخادم ننزل للحسابات المحلية
     القديمة (بصمة SHA-256 مع ملح) كاحتياط فقط — لا كلمة مرور صريحة أبداً.
   ★ الإنشاء يستدعي validation.js أولاً (إيميل صحيح، كلمة مرور ٨ خانات
     بحرفين ورقم على الأقل، وتأكيد مطابق).
   ============================================================ */

import { useCallback, useEffect, useRef, useState } from "react";
import { Link, useLocation, useNavigate } from "react-router-dom";
import { PATHS } from "../../routes.js";
import { usePageMeta } from "../../usePageMeta.js";
import { useAppDispatch, useAppSelector } from "../../redux/hooks.js";
import { userActions } from "../../redux/slices/userSlice.js";
import { uiActions } from "../../redux/slices/uiSlice.js";
import { validateLogin, validateRegister, passwordStrength, passwordStrengthLabel } from "../../validation.js";
import { serverSignup, serverLogin, serverGoogleLogin, applyServerSession, beginAuthAttempt } from "../../api/auth.js";
import GoogleSignIn from "./GoogleSignIn.jsx";
import { Icon } from "./Icons.jsx";
import { ATYAB_TERMS } from "../../data/appConfig.js";
import { T } from "../../i18n.js";

/* ---------- الملح والتجزئة ---------- */
function makeSalt() {
  try {
    const a = new Uint8Array(12);
    window.crypto.getRandomValues(a);
    return Array.prototype.map
      .call(a, function (b) {
        return ("0" + b.toString(16)).slice(-2);
      })
      .join("");
  } catch (e) {
    return Math.random().toString(36).slice(2, 10) + Date.now().toString(36);
  }
}

function sha256(text) {
  const subtle = window.crypto && window.crypto.subtle;
  if (subtle && subtle.digest && window.TextEncoder) {
    try {
      return subtle.digest("SHA-256", new TextEncoder().encode(text)).then(function (buf) {
        return Array.prototype.map
          .call(new Uint8Array(buf), function (b) {
            return ("0" + b.toString(16)).slice(-2);
          })
          .join("");
      });
    } catch (e) {
      /* نتابع إلى الاحتياط */
    }
  }
  let h1 = 0x811c9dc5;
  let h2 = 0x1000193;
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i);
    h1 = ((h1 ^ c) * 0x01000193) >>> 0;
    h2 = ((h2 << 5) + h2 + c) >>> 0;
  }
  return Promise.resolve("fallback-" + h1.toString(16) + h2.toString(16));
}

export default function LogIn(props) {
  const dispatch = useAppDispatch();
  const navigate = useNavigate();
  const accounts = useAppSelector(function (s) {
    return s.user.accounts;
  });
  const session = useAppSelector(function (s) {
    return s.user.session;
  });
  /* ★ الربط الحقيقي وحده يفتح نافذة «مسجل» — الجلسة المحلية وحدها
     تسقط للنموذج أدناه (مع تعبئة البريد) لا للنافذة العالقة. */
  const customerId = useAppSelector(function (s) {
    return s.user.auth && s.user.auth.customerId;
  });
  const profile = useAppSelector(function (s) {
    return s.user.profile;
  });
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });

  const mode = props.mode === "login" ? "login" : "signup";

  /* ★ من أين جاء؟ «إتمام الدفع» يمرّر { from: "/checkout" } — بعد النجاح
     نعود إليه ليُكمل العميل بيانات التوصيل بنفسه؛ والدخول المباشر من
     «سجل الآن» بلا returnTo فيبقى حرّاً ولا نطلب منه شيئاً. */
  const location = useLocation();
  const returnTo = (location.state && location.state.from) || "";

  usePageMeta({
    route: mode === "login" ? "login" : "register",
    titleAr: mode === "login" ? "تسجيل الدخول" : "إنشاء حساب",
    titleEn: mode === "login" ? "Log in" : "Sign up"
  });
  const [values, setValues] = useState({
    email: "",
    password: "",
    confirm: "",
    agree: true
  });
  const [errors, setErrors] = useState({});
  const [busy, setBusy] = useState(false);
  const [showPass, setShowPass] = useState(false);
  const firstRef = useRef(null);
  const panelRef = useRef(null);

  /* تغيير الوضع (دخول ↔ تسجيل) يُصفّر الأخطاء — أثناء الرسم لا في
     effect، بنفس طريقة React المعتمدة (مقارنة نسخة ثم setState مرة). */
  const [seenMode, setSeenMode] = useState(mode);
  if (seenMode !== mode) {
    setSeenMode(mode);
    setErrors({});
  }

  /* ★ بريد الجلسة المحلية يُعبَّأ في حقل البريد مرة واحدة — العميل
     العائد لا يكتب بريده من جديد، فقط كلمة المرور. */
  const [seenSessionMail, setSeenSessionMail] = useState("");
  if (session && !seenSessionMail) {
    setSeenSessionMail(session);
    setValues(function (prev) {
      return prev.email ? prev : Object.assign({}, prev, { email: session });
    });
  }

  useEffect(
    function () {
      const t = window.setTimeout(function () {
        if (firstRef.current) {
          try {
            firstRef.current.focus({ preventScroll: true });
          } catch (e) {
            firstRef.current.focus();
          }
        }
      }, 90);
      return function () {
        window.clearTimeout(t);
      };
    },
    [mode]
  );

  /* إغلاق شاشة الدخول/التسجيل = العودة إلى الصفحة الرئيسية */
  const close = useCallback(
    function () {
      navigate(PATHS.home);
    },
    [navigate]
  );

  /* إغلاق بمفتاح Escape */
  useEffect(
    function () {
      function onKey(e) {
        if (e.key === "Escape") close();
      }
      document.addEventListener("keydown", onKey);
      return function () {
        document.removeEventListener("keydown", onKey);
      };
    },
    [close]
  );

  /* ★ مسجَّل خادم يزور الدخول؟ ارتداد فوري لصاحب الدعوة أو الحساب —
     لا نموذج ولا نافذة لمن لا يحتاجهما. */
  useEffect(
    function () {
      if (customerId) navigate(returnTo || PATHS.profile, { replace: true });
    },
    [customerId, returnTo, navigate]
  );

  function setField(key, value) {
    setValues(function (prev) {
      return Object.assign({}, prev, { [key]: value });
    });
    setErrors(function (prev) {
      return Object.assign({}, prev, { [key]: "" });
    });
  }

  /* نجاح الخادم: تثبيت التوكن + دخول، ثم عودة لصاحب الدعوة أو لصفحة
     المنتجات مباشرة (لا صفحة المعلومات) — الدخول الجديد يرى البضاعة أمامه.
     ★ حساب جديد تماماً؟ نصفّر الملف المحلي أولاً حتى لا يرى العميل الجديد
     بيانات عميل سابق على نفس المتصفح — الحقول تبدأ فارغة. */
  /* ★ #8: gen عند بدء المحاولة — استجابة حساب سابق بعد تبديله تُتجاهل */
  const attemptGenRef = { current: null };
  function afterServerAuth(data, verb, fresh, attemptGen) {
    /* ★ v15-F5: انتقال محروس واحد — حراسة الجيل داخل applyServerSession
       (تُرجع null للمرفوض)، والمسح عند تبديل الهوية داخل sessionEstablished.
       هنا: لا mutation قبل القبول، ولا toast/تنقل عند رد قديم مرفوض.
       التسجيل الجديد (fresh) يبدأ نظيفاً بعد القبول مع تثبيت بريده. */
    const saved = applyServerSession(dispatch, data || {}, profile, attemptGen != null ? attemptGen : attemptGenRef.current);
    setBusy(false);
    if (!saved) return;
    if (fresh) {
      try {
        dispatch(userActions.resetProfile());
        const nm = String((data && (data.email || data.Email)) || "").trim().toLowerCase();
        if (nm) dispatch(userActions.setProfile({ email: nm }));
      } catch (e) {}
    }
    dispatch(uiActions.toastShown(verb));
    setTimeout(function () {
      if (returnTo) navigate(returnTo);
      else navigate(PATHS.perfumes);
    }, 700);
  }

  function serverMsg(err, fallback) {
    const m = String((err && err.message) || "").trim();
    return m || fallback;
  }

  /* ★ الدخول بجوجل: idToken الخام → الخادم (يتحقق لدى Google ويرجع
     نفس الجلسة) — ثم نفس طريق النجاح: دخول + عودة لصاحب الدعوة. */
  function googleCredential(idToken) {
    if (busy) return;
    setBusy(true);
    attemptGenRef.current = beginAuthAttempt();
    const myGen = attemptGenRef.current;
    serverGoogleLogin(idToken).then(
      function (data) {
        afterServerAuth(
          data,
          mode === "signup" ? "تم إنشاء حسابك بجوجل — أهلاً بك في أطياب الجاسم" : "تم تسجيل الدخول بجوجل — أهلاً بعودتك",
          mode === "signup",
          myGen
        );
      },
      function (err) {
        setBusy(false);
        /* ★ 503 = عطل في تحقق الخادم لدى Google (إعدادات server-side) —
           ليست مشكلة العميل، فنقولها بوضوح ونقترح البديل */
        if (err && err.status === 503) {
          dispatch(uiActions.toastShown("الدخول بجوجل متوقف مؤقتاً — ادخل بالبريد وكلمة المرور أو حاول لاحقاً."));
          return;
        }
        if (err && (err.code === "ENETUNREACH" || err.status === 0)) {
          dispatch(uiActions.toastShown("تعذّر الوصول إلى الخادم — تحقق من الاتصال وحاول مجدداً."));
          return;
        }
        const msg = serverMsg(err, "تعذّر الدخول بجوجل — حاول مجدداً.");
        dispatch(uiActions.toastShown(msg));
      }
    );
  }

  function submit(e) {
    if (e) e.preventDefault();
    if (busy) return;
    const signup = mode === "signup";
    const result = signup ? validateRegister(values) : validateLogin(values);
    setErrors(result.errors);
    if (!result.valid) {
      dispatch(uiActions.toastShown(result.firstError));
      return;
    }

    const email = String(values.email).trim().toLowerCase();
    setBusy(true);

    /* ---------- الدخول: الخادم أولاً ---------- */
    if (!signup) {
      attemptGenRef.current = beginAuthAttempt();
      const myGen = attemptGenRef.current;
      serverLogin({ email: email, password: values.password }).then(
        function (data) {
          afterServerAuth(data, "تم تسجيل الدخول — أهلاً بعودتك", false, myGen);
        },
        function (err) {
          /* بلا خادم → الحسابات المحلية القديمة كاحتياط فقط */
          if (err && (err.code === "ENETUNREACH" || err.status === 0)) {
            const account = accounts[email];
            if (!account) {
              setBusy(false);
              setErrors({ email: "لا يوجد حساب بهذا البريد على هذا الجهاز — أنشئ حساباً جديداً." });
              return;
            }
            sha256(account.salt + "|" + values.password).then(function (hash) {
              if (hash !== account.hash) {
                setBusy(false);
                setErrors({ password: "كلمة المرور غير صحيحة." });
                dispatch(uiActions.toastShown("كلمة المرور غير صحيحة"));
                return;
              }
              dispatch(userActions.setSession(email));
              /* ★ #19: بريد مختلف عن المخزن؟ صفّر الملف أولاً (لا عنوان A لـB)
                 — ينطبق على الدخول المحلي أيضاً. */
              try {
                const oldMailLocal = String((profile && profile.email) || "").trim().toLowerCase();
                if (oldMailLocal && oldMailLocal !== email) dispatch(userActions.resetProfile());
              } catch (e) {}
              setBusy(false);
              /* ★ #19: دخول محلي (بلا خادم) = وضع الجهاز فقط — لا مزامنة ولا
                 طلبات خادمية؛ يُقال صراحة بدل عرض «تم تسجيل الدخول» العامة. */
              dispatch(uiActions.toastShown("تم الدخول على هذا الجهاز فقط (الخادم غير متاح) — سجّل بالخادم للمزامنة والطلب"));
              setTimeout(function () {
                if (returnTo) navigate(returnTo);
                else navigate(PATHS.perfumes);
              }, 900);
            });
            return;
          }
          setBusy(false);
          const msg = serverMsg(err, "بيانات الدخول غير صحيحة.");
          setErrors({ password: msg });
          dispatch(uiActions.toastShown(msg));
        }
      );
      return;
    }

    /* ---------- التسجيل: الخادم أولاً (يرجع التوكن مباشرة — بلا Login ثانٍ) ---------- */
    attemptGenRef.current = beginAuthAttempt();
    const myGenSignup = attemptGenRef.current;
    serverSignup({ email: email, password: values.password, confirm: values.confirm }).then(
      function (data) {
        afterServerAuth(data, "تم إنشاء حسابك — أهلاً بك في أطياب الجاسم", true, myGenSignup);
      },
      function (err) {
        /* بلا خادم → حساب محلي على الجهاز فقط */
        if (err && (err.code === "ENETUNREACH" || err.status === 0)) {
          if (accounts[email]) {
            setBusy(false);
            setErrors({ email: "هذا البريد مسجّل مسبقاً — استخدم «تسجيل الدخول»." });
            return;
          }
          const salt = makeSalt();
          sha256(salt + "|" + values.password).then(function (hash) {
            dispatch(userActions.resetProfile());
            dispatch(
              userActions.registerAccount({
                email: email,
                salt: salt,
                hash: hash
              })
            );
            dispatch(userActions.setProfile({ email: email }));
            setBusy(false);
            dispatch(uiActions.toastShown("الخادم غير متاح — حُفظ حسابك على هذا الجهاز"));
            setTimeout(function () {
              if (returnTo) navigate(returnTo);
              else navigate(PATHS.perfumes);
            }, 900);
          });
          return;
        }
        setBusy(false);
        const msg = serverMsg(err, "تعذّر إنشاء الحساب — حاول مجدداً.");
        const low = msg.toLowerCase();
        if (low.indexOf("mail") !== -1 || msg.indexOf("بريد") !== -1 || msg.indexOf("مسجّل") !== -1 || low.indexOf("exist") !== -1 || low.indexOf("taken") !== -1) {
          setErrors({ email: msg });
        } else {
          setErrors({ password: msg });
        }
        dispatch(uiActions.toastShown(msg));
      }
    );
  }

  const signup = mode === "signup";
  const strength = signup && values.password ? passwordStrength(values.password) : 0;

  function field(o) {
    const bad = !!errors[o.name];
    const isPass = o.type === "password";
    return (
      <div className={"rg-field" + (o.wide ? " is-wide" : "") + (bad ? " is-bad" : "")}>
        <label className="rg-label" htmlFor={"rg-" + o.name}>
          {o.label}
        </label>
        <div className={isPass ? "rg-pass" : ""}>
          <input
            ref={o.first ? firstRef : undefined}
            className="rg-input"
            id={"rg-" + o.name}
            type={isPass && showPass ? "text" : o.type || "text"}
            dir={o.dir === undefined ? "ltr" : o.dir}
            inputMode={o.inputMode}
            maxLength={o.maxLength}
            autoComplete={o.autoComplete}
            placeholder={o.placeholder}
            value={o.value == null ? "" : o.value}
            onChange={function (e) {
              setField(o.name, o.type === "checkbox" ? e.target.checked : e.target.value);
            }}
          />
          {isPass ? (
            <button
              className="rg-eye"
              type="button"
              aria-label={showPass ? "إخفاء كلمة المرور" : "إظهار كلمة المرور"}
              aria-pressed={showPass ? "true" : "false"}
              onClick={function () {
                setShowPass(!showPass);
              }}
            >
              <Icon name={showPass ? "eyeOff" : "eye"} />
            </button>
          ) : null}
        </div>
        <span className="rg-err" hidden={!errors[o.name]}>
          {errors[o.name] || ""}
        </span>
      </div>
    );
  }

  /* ---------- حالة «مسجَّل الدخول» (ربط خادم حقيقي فقط) ---------- */
  if (customerId) {
    return (
      <div id="registerScreen" className="screen is-open" role="dialog" aria-modal="true" aria-labelledby="loginTitle">
        <button className="screen-backdrop" type="button" tabIndex={-1} aria-hidden="true" onClick={close} />
        <div className="screen-panel rg-panel is-solo" ref={panelRef}>
          <div className="screen-head">
            <h2 id="loginTitle">حسابي</h2>
            <button className="screen-close" type="button" aria-label="إغلاق" onClick={close}>
              <Icon name="x" strokeWidth={2} />
            </button>
          </div>
          <div className="screen-body rg-body">
            <div className="rg-logged">
              <span className="rg-avatar" aria-hidden="true">
                {(session.trim()[0] || "؟").toUpperCase()}
              </span>
              <p className="rg-logged-mail">{session}</p>
              <p className="rg-logged-sub">
                أنت مسجّل الدخول في هذا الجهاز. كل ما تضيفه للعربة أو للمفضلة محفوظ لك هنا.
              </p>
              <button
                className="rg-submit"
                type="button"
                onClick={function () {
                  navigate(returnTo || PATHS.profile);
                }}
              >
                {returnTo ? "متابعة" : "الذهاب إلى حسابي"}
                <Icon name="back" strokeWidth={2} />
              </button>
              <button
                className="rg-switch"
                type="button"
                onClick={function () {
                  dispatch(userActions.logout());
                  dispatch(uiActions.toastShown("تم تسجيل الخروج من هذا الجهاز"));
                }}
              >
                تسجيل الخروج من هذا الجهاز
              </button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div id="registerScreen" className="screen is-open" role="dialog" aria-modal="true" aria-labelledby="loginTitle">
      <button className="screen-backdrop" type="button" tabIndex={-1} aria-hidden="true" onClick={close} />

      <div className="screen-panel rg-panel" ref={panelRef}>
        <div className="rg-main">
          <div className="screen-head">
            <h2 id="loginTitle">{signup ? "إنشاء حساب" : "تسجيل الدخول"}</h2>
            <button className="screen-close" type="button" aria-label="إغلاق" onClick={close}>
              <Icon name="x" strokeWidth={2} />
            </button>
          </div>

          <div className="screen-body rg-body">
          <div className="rg-head">
            <span className="rg-badge" aria-hidden="true">
              <Icon name="userPlus" />
            </span>
            <h3 className="rg-title">{signup ? "إنشاء حساب جديد" : "تسجيل الدخول"}</h3>
            <p className="rg-sub">
              {signup
                ? "سجّل ببريدك الإلكتروني لتتابع طلباتك وتطلب بخوراً مخصّصاً باسمك."
                : "أدخل بريدك وكلمة المرور للمتابعة إلى حسابك."}
            </p>
          </div>

          <form className="rg-form rg-grid" id="rgForm" noValidate onSubmit={submit}>
            {/* ★ التسجيل المختصر: بريد + كلمة مرور + تأكيد فقط —
               بقية البيانات (الاسم/الجوال/العنوان) تُطلب عند تأكيد الطلب */}

            {field({
              name: "email",
              label: "البريد الإلكتروني",
              type: "email",
              value: values.email,
              first: true,
              autoComplete: "email",
              placeholder: "name@example.com",
              wide: true
            })}

            {field({
              name: "password",
              label: "كلمة المرور",
              type: "password",
              value: values.password,
              autoComplete: signup ? "new-password" : "current-password",
              wide: !signup
            })}

            {signup
              ? field({
                  name: "confirm",
                  label: "تأكيد كلمة المرور",
                  type: "password",
                  value: values.confirm,
                  autoComplete: "new-password"
                })
              : null}

            {signup ? (
              <div className="rg-strength" data-level={strength}>
                <span className="rg-strength-bar">
                  <i style={{ width: (strength === 2 ? 100 : strength === 1 ? 55 : 22) + "%" }} />
                </span>
                <span className="rg-strength-text">
                  قوّة كلمة المرور: <b>{passwordStrengthLabel(values.password)}</b> — ٨ خانات على الأقل (والأفضل ١٢)
                  مع حرفين ورقم.
                </span>
              </div>
            ) : null}

            {signup ? (
              <div className={"rg-field is-wide rg-check-field" + (errors.agree ? " is-bad" : "")}>
                <details className="rg-terms">
                  <summary>
                    <Icon name="doc" strokeWidth={1.7} />
                    <span>الشروط والأحكام وسياسة الخصوصية</span>
                  </summary>
                  <div className="rg-terms-body">
                    <p>{T(ATYAB_TERMS.intro, language)}</p>
                    {ATYAB_TERMS.clauses.map(function (clause, i) {
                      return (
                        <p key={i}>
                          <b>
                            {clause.n}. {T(clause.title, language)}
                          </b>{" "}
                          — {T(clause.body, language)}
                        </p>
                      );
                    })}
                    <p>{T(ATYAB_TERMS.contact, language)}</p>
                  </div>
                </details>
                <label className="rg-check">
                  <input
                    type="radio"
                    name="rgAgree"
                    value="yes"
                    checked={values.agree === true}
                    onChange={function () {
                      setField("agree", true);
                    }}
                  />
                  <span>أوافق على الشروط والأحكام وسياسة الخصوصية (نسخة {ATYAB_TERMS.version}).</span>
                </label>
                <span className="rg-err" hidden={!errors.agree}>
                  {errors.agree || ""}
                </span>
              </div>
            ) : null}
          </form>

          <GoogleSignIn
            mode={mode}
            onCredential={googleCredential}
            onError={function () {
              dispatch(uiActions.toastShown("تعذّر تحميل زر جوجل — تحقق من الاتصال وحاول مجدداً."));
            }}
          />

          <div className="rg-actions">
            <button className="rg-submit" id="rgSubmit" type="submit" form="rgForm" disabled={busy}>
              {busy ? "لحظة…" : signup ? "إنشاء الحساب" : "تسجيل الدخول"}
              {busy ? null : <Icon name="back" strokeWidth={2} />}
            </button>
            <button
              className="rg-switch"
              type="button"
              onClick={function () {
                navigate(signup ? PATHS.login : PATHS.register, returnTo ? { state: { from: returnTo } } : undefined);
              }}
            >
              {signup ? (
                <>
                  لديّ حساب بالفعل — <b>تسجيل الدخول</b>
                </>
              ) : (
                <>
                  ما عندك حساب؟ — <b>إنشاء حساب جديد</b>
                </>
              )}
            </button>
          </div>

          <p className="rg-note">
            <Icon name="lock" strokeWidth={1.7} />
            <span>
              حسابك وعربتك وطلباتك ومفضلتك محفوظة على هذا الجهاز (وكلمة المرور تُخزَّن مُجزَّأة).
            </span>
          </p>
          {/* ★ OP1 §6: الدخول وفق أحدث الشروط — بيان صريح برابط، وبلا
              إرسال checkboxAccepted من تلقاء الواجهة (سياسة LoginAuto للباك). */}
          {!signup ? (
            <p className="rg-note">
              <Icon name="doc" strokeWidth={1.7} />
              <span>
                بتسجيل الدخول أنت توافق على أحدث{" "}
                <Link to={PATHS.legal}>الشروط والأحكام وسياسة الخصوصية</Link>
                {" "}(نسخة {ATYAB_TERMS.version}).
              </span>
            </p>
          ) : null}
          </div>
        </div>

        <aside className="rg-aside" aria-hidden="true">
          <span className="rg-aside-glow" />
          <span className="rg-aside-mark">
            <Icon name="flame" strokeWidth={1.6} />
          </span>
          <div className="rg-aside-brand">
            <b>أطياب الجاسم</b>
            <i>ATYAB AL-JASEM</i>
          </div>
          <h3 className="rg-aside-title">عبقٌ يبقى في الذاكرة</h3>
          <p className="rg-aside-text">
            عطور وبخور مركّبة بعناية من أجود المواد الخام، بتوقيعٍ شرقيٍّ يفوح فخامةً وأصالة.
          </p>
          <ul className="rg-aside-list">
            <li>
              <Icon name="spark" strokeWidth={1.7} />
              <span>عطور وبخور أصلية مختارة يدوياً</span>
            </li>
            <li>
              <Icon name="truck" strokeWidth={1.7} />
              <span>توصيل سريع داخل الإمارات والخليج</span>
            </li>
            <li>
              <Icon name="shield" strokeWidth={1.7} />
              <span>حسابك وبياناتك محفوظة على هذا الجهاز</span>
            </li>
          </ul>
          <span className="rg-aside-foot">من الإمارات وإلى العالم</span>
        </aside>
      </div>
    </div>
  );
}
